"""Parser: turns a token stream into an AST.

The AST nodes are plain data holders; all behaviour lives in the evaluator.
"""

from .errors import ParseError
from .lexer import tokenize

_COMPARISON_OPS = frozenset({"==", "!=", "<", "<=", ">", ">="})


class Node:
    """Base class for AST nodes."""

    __slots__ = ("position",)

    _fields = ()

    def __repr__(self):
        parts = ", ".join(repr(getattr(self, name)) for name in self._fields)
        return f"{type(self).__name__}({parts})"

    def __eq__(self, other):
        if type(other) is not type(self):
            return NotImplemented
        return all(getattr(self, f) == getattr(other, f) for f in self._fields)

    def __hash__(self):
        return hash((type(self).__name__,) + tuple(
            tuple(v) if isinstance(v, list) else v
            for v in (getattr(self, f) for f in self._fields)
        ))


class Literal(Node):
    """A number, string or boolean constant."""

    __slots__ = ("value",)
    _fields = ("value",)

    def __init__(self, value, position=None):
        self.value = value
        self.position = position


class Variable(Node):
    """An identifier looked up in the environment."""

    __slots__ = ("name",)
    _fields = ("name",)

    def __init__(self, name, position=None):
        self.name = name
        self.position = position


class UnaryOp(Node):
    """``-x`` or ``not x``."""

    __slots__ = ("op", "operand")
    _fields = ("op", "operand")

    def __init__(self, op, operand, position=None):
        self.op = op
        self.operand = operand
        self.position = position


class BinaryOp(Node):
    """An arithmetic or comparison operation."""

    __slots__ = ("op", "left", "right")
    _fields = ("op", "left", "right")

    def __init__(self, op, left, right, position=None):
        self.op = op
        self.left = left
        self.right = right
        self.position = position


class LogicalOp(Node):
    """``and`` / ``or`` — kept separate because they short-circuit."""

    __slots__ = ("op", "left", "right")
    _fields = ("op", "left", "right")

    def __init__(self, op, left, right, position=None):
        self.op = op
        self.left = left
        self.right = right
        self.position = position


class Call(Node):
    """A call to a built-in function."""

    __slots__ = ("name", "args")
    _fields = ("name", "args")

    def __init__(self, name, args, position=None):
        self.name = name
        self.args = args
        self.position = position


class _Parser:
    def __init__(self, tokens, end_position):
        self._tokens = tokens
        self._index = 0
        self._end = end_position

    # -- token helpers -------------------------------------------------
    def _peek(self):
        if self._index < len(self._tokens):
            return self._tokens[self._index]
        return None

    def _position(self):
        token = self._peek()
        return self._end if token is None else token.position

    def _describe(self):
        token = self._peek()
        if token is None:
            return "end of input"
        if token.kind == "NUMBER":
            return f"number {token.value!r}"
        if token.kind == "STRING":
            return "string"
        return repr(token.value)

    def _advance(self):
        token = self._tokens[self._index]
        self._index += 1
        return token

    def _check_op(self, *values):
        token = self._peek()
        return token is not None and token.kind == "OP" and token.value in values

    def _check_keyword(self, *values):
        token = self._peek()
        return token is not None and token.kind == "KEYWORD" and token.value in values

    def _expect_op(self, value):
        if not self._check_op(value):
            raise ParseError(
                f"expected {value!r} but found {self._describe()}", self._position()
            )
        return self._advance()

    # -- grammar -------------------------------------------------------
    def parse_program(self):
        if self._peek() is None:
            raise ParseError("unexpected end of input: expected an expression", self._end)
        node = self.parse_expr()
        if self._peek() is not None:
            raise ParseError(
                f"unexpected trailing input: {self._describe()}", self._position()
            )
        return node

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self._check_keyword("or"):
            token = self._advance()
            right = self.parse_and()
            node = LogicalOp("or", node, right, token.position)
        return node

    def parse_and(self):
        node = self.parse_not()
        while self._check_keyword("and"):
            token = self._advance()
            right = self.parse_not()
            node = LogicalOp("and", node, right, token.position)
        return node

    def parse_not(self):
        if self._check_keyword("not"):
            token = self._advance()
            return UnaryOp("not", self.parse_not(), token.position)
        return self.parse_comparison()

    def parse_comparison(self):
        node = self.parse_additive()
        if self._peek() is not None and self._check_op(*_COMPARISON_OPS):
            token = self._advance()
            right = self.parse_additive()
            node = BinaryOp(token.value, node, right, token.position)
            if self._check_op(*_COMPARISON_OPS):
                # Rule 11: comparison operators do not chain.
                raise ParseError(
                    "comparison operators are non-associative", self._position()
                )
        return node

    def parse_additive(self):
        node = self.parse_multiplicative()
        while self._check_op("+", "-"):
            token = self._advance()
            right = self.parse_multiplicative()
            node = BinaryOp(token.value, node, right, token.position)
        return node

    def parse_multiplicative(self):
        node = self.parse_unary()
        while self._check_op("*", "/", "%"):
            token = self._advance()
            right = self.parse_unary()
            node = BinaryOp(token.value, node, right, token.position)
        return node

    def parse_unary(self):
        if self._check_op("-"):
            token = self._advance()
            return UnaryOp("-", self.parse_unary(), token.position)
        return self.parse_power()

    def parse_power(self):
        node = self.parse_primary()
        if self._check_op("^"):
            token = self._advance()
            # Right operand is a `unary`, which makes `^` right-associative
            # and allows `2 ^ -1`.
            right = self.parse_unary()
            node = BinaryOp("^", node, right, token.position)
        return node

    def parse_primary(self):
        token = self._peek()
        if token is None:
            raise ParseError("unexpected end of input: expected an expression", self._end)

        if token.kind == "NUMBER" or token.kind == "STRING":
            self._advance()
            return Literal(token.value, token.position)

        if token.kind == "KEYWORD":
            if token.value in ("true", "false"):
                self._advance()
                return Literal(token.value == "true", token.position)
            raise ParseError(
                f"unexpected keyword {token.value!r}", token.position
            )

        if token.kind == "IDENT":
            self._advance()
            if self._check_op("("):
                self._advance()
                args = []
                if not self._check_op(")"):
                    args.append(self.parse_expr())
                    while self._check_op(","):
                        self._advance()
                        args.append(self.parse_expr())
                self._expect_op(")")
                return Call(token.value, args, token.position)
            return Variable(token.value, token.position)

        if token.kind == "OP" and token.value == "(":
            self._advance()
            node = self.parse_expr()
            self._expect_op(")")
            return node

        raise ParseError(f"unexpected token {self._describe()}", token.position)


def parse(source):
    """Parse ``source`` and return the AST root node.

    Parsing performs no evaluation, so ``parse("1 / 0")`` succeeds.
    """
    tokens = tokenize(source)
    return _Parser(tokens, len(source)).parse_program()

"""Built-in functions and value formatting for minilang."""

import math

from .errors import EvalError


def is_number(value):
    """True for minilang numbers (``bool`` is deliberately excluded)."""
    return isinstance(value, float) and not isinstance(value, bool)


def is_string(value):
    return isinstance(value, str)


def is_boolean(value):
    return isinstance(value, bool)


def is_value(value):
    return is_boolean(value) or is_number(value) or is_string(value)


def format_number(value):
    """Format a minilang number the way the REPL does (rule 33)."""
    if math.isfinite(value) and value.is_integer():
        return str(int(value))
    return repr(value)


def escape_string(value):
    """Re-escape a string's contents (without surrounding quotes)."""
    out = []
    for ch in value:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        else:
            out.append(ch)
    return "".join(out)


def format_value(value):
    """Format any minilang value for display (REPL and ``:vars``)."""
    if is_boolean(value):
        return "true" if value else "false"
    if is_number(value):
        return format_number(value)
    if is_string(value):
        return '"' + escape_string(value) + '"'
    raise EvalError(f"unsupported value: {value!r}")


def _arity_error(name, expected, got):
    return EvalError(f"{name}() takes {expected} argument(s), got {got}")


def _check_arity(name, args, expected):
    if len(args) != expected:
        raise _arity_error(name, expected, len(args))


def _check_number(name, value, ordinal=None):
    if not is_number(value):
        where = "" if ordinal is None else f" (argument {ordinal})"
        raise EvalError(f"{name}() expects a number{where}, got {_type_name(value)}")
    return value


def _check_string(name, value, ordinal=None):
    if not is_string(value):
        where = "" if ordinal is None else f" (argument {ordinal})"
        raise EvalError(f"{name}() expects a string{where}, got {_type_name(value)}")
    return value


def _type_name(value):
    if is_boolean(value):
        return "boolean"
    if is_number(value):
        return "number"
    if is_string(value):
        return "string"
    return type(value).__name__


def _builtin_abs(args):
    _check_arity("abs", args, 1)
    return float(abs(_check_number("abs", args[0])))


def _builtin_min(args):
    if not args:
        raise _arity_error("min", "at least 1", 0)
    for index, arg in enumerate(args, start=1):
        _check_number("min", arg, index)
    return float(min(args))


def _builtin_max(args):
    if not args:
        raise _arity_error("max", "at least 1", 0)
    for index, arg in enumerate(args, start=1):
        _check_number("max", arg, index)
    return float(max(args))


def _builtin_round(args):
    if len(args) not in (1, 2):
        raise _arity_error("round", "1 or 2", len(args))
    x = _check_number("round", args[0], 1)
    if len(args) == 1:
        return float(round(x))
    digits = _check_number("round", args[1], 2)
    if not math.isfinite(digits) or not digits.is_integer():
        raise EvalError("round() expects a whole number of digits")
    return float(round(x, int(digits)))


def _builtin_len(args):
    _check_arity("len", args, 1)
    return float(len(_check_string("len", args[0])))


def _builtin_upper(args):
    _check_arity("upper", args, 1)
    return _check_string("upper", args[0]).upper()


def _builtin_lower(args):
    _check_arity("lower", args, 1)
    return _check_string("lower", args[0]).lower()


def _builtin_str(args):
    _check_arity("str", args, 1)
    value = args[0]
    if is_string(value):
        # A string converts to itself; the surrounding quotes shown by the
        # REPL are a display concern, not part of the value.
        return value
    if is_boolean(value):
        return "true" if value else "false"
    if is_number(value):
        return format_number(value)
    raise EvalError(f"str() expects a value, got {_type_name(value)}")


def _builtin_num(args):
    _check_arity("num", args, 1)
    text = _check_string("num", args[0])
    try:
        return float(text)
    except ValueError:
        raise EvalError(f"cannot convert to number: {text!r}") from None


#: Eagerly-evaluated built-ins: name -> callable taking the argument list.
BUILTINS = {
    "abs": _builtin_abs,
    "min": _builtin_min,
    "max": _builtin_max,
    "round": _builtin_round,
    "len": _builtin_len,
    "upper": _builtin_upper,
    "lower": _builtin_lower,
    "str": _builtin_str,
    "num": _builtin_num,
}

#: Built-ins whose arguments must not all be evaluated up front.
LAZY_BUILTINS = frozenset({"if"})

#: Every callable name known to minilang.
BUILTIN_NAMES = frozenset(BUILTINS) | LAZY_BUILTINS


def check_if_arity(argument_count):
    """Arity check for the lazy ``if`` built-in."""
    if argument_count != 3:
        raise _arity_error("if", 3, argument_count)


def check_if_condition(value):
    if not is_boolean(value):
        raise EvalError(f"if() expects a boolean condition, got {_type_name(value)}")
    return value

"""Evaluator: walks the AST and produces minilang values."""

import math

from .builtins import (
    BUILTINS,
    BUILTIN_NAMES,
    LAZY_BUILTINS,
    check_if_arity,
    check_if_condition,
    is_boolean,
    is_number,
    is_string,
    is_value,
)
from .errors import EvalError
from .parser import BinaryOp, Call, Literal, LogicalOp, UnaryOp, Variable, parse

_ORDER_OPS = frozenset({"<", "<=", ">", ">="})


def _type_name(value):
    if is_boolean(value):
        return "boolean"
    if is_number(value):
        return "number"
    if is_string(value):
        return "string"
    return type(value).__name__


def _require_number(value, context):
    if not is_number(value):
        raise EvalError(f"{context} requires numbers, got {_type_name(value)}")
    return value


def _lookup(env, name):
    if name not in env:
        raise EvalError(f"undefined variable: {name}")
    value = env[name]
    if not is_value(value):
        # Rule 26: env values are validated lazily, when the name is read.
        raise EvalError(f"unsupported value for {name}: {value!r}")
    return value


def _eval_arithmetic(op, left, right):
    if op == "+":
        if is_number(left) and is_number(right):
            return left + right
        if is_string(left) and is_string(right):
            return left + right
        raise EvalError(
            "'+' requires two numbers or two strings, got "
            f"{_type_name(left)} and {_type_name(right)}"
        )

    _require_number(left, f"'{op}'")
    _require_number(right, f"'{op}'")

    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        if right == 0:
            raise EvalError("division by zero")
        return left / right
    if op == "%":
        if right == 0:
            raise EvalError("modulo by zero")
        return left % right
    if op == "^":
        try:
            result = left**right
        except ZeroDivisionError:
            raise EvalError("division by zero") from None
        except (OverflowError, ValueError):
            raise EvalError("'^' produced a result that is not a real number") from None
        if isinstance(result, complex) or (
            isinstance(result, float) and math.isnan(result) and not _nan_input(left, right)
        ):
            raise EvalError("'^' produced a result that is not a real number")
        return float(result)
    raise EvalError(f"unknown operator: {op}")  # pragma: no cover - defensive


def _nan_input(left, right):
    return math.isnan(left) or math.isnan(right)


def _eval_comparison(op, left, right):
    if op == "==":
        return _values_equal(left, right)
    if op == "!=":
        return not _values_equal(left, right)

    both_numbers = is_number(left) and is_number(right)
    both_strings = is_string(left) and is_string(right)
    if not (both_numbers or both_strings):
        raise EvalError(
            f"'{op}' requires two numbers or two strings, got "
            f"{_type_name(left)} and {_type_name(right)}"
        )
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    return left >= right


def _values_equal(left, right):
    # Rule 19: different types are never equal, so `true == 1` is false
    # (Python would say True).
    if type(left) is not type(right):
        return False
    return left == right


class _Evaluator:
    def __init__(self, env):
        self.env = env

    def eval(self, node):
        if isinstance(node, Literal):
            return node.value
        if isinstance(node, Variable):
            return _lookup(self.env, node.name)
        if isinstance(node, UnaryOp):
            return self._eval_unary(node)
        if isinstance(node, BinaryOp):
            return self._eval_binary(node)
        if isinstance(node, LogicalOp):
            return self._eval_logical(node)
        if isinstance(node, Call):
            return self._eval_call(node)
        raise EvalError(f"cannot evaluate node: {node!r}")  # pragma: no cover

    def _eval_unary(self, node):
        value = self.eval(node.operand)
        if node.op == "-":
            if not is_number(value):
                raise EvalError(f"unary '-' requires a number, got {_type_name(value)}")
            return -value
        if not is_boolean(value):
            raise EvalError(f"'not' requires a boolean, got {_type_name(value)}")
        return not value

    def _eval_binary(self, node):
        left = self.eval(node.left)
        right = self.eval(node.right)
        if node.op in _ORDER_OPS or node.op in ("==", "!="):
            return _eval_comparison(node.op, left, right)
        return _eval_arithmetic(node.op, left, right)

    def _eval_logical(self, node):
        left = self.eval(node.left)
        if not is_boolean(left):
            raise EvalError(
                f"'{node.op}' requires booleans, got {_type_name(left)}"
            )
        if node.op == "and" and left is False:
            return False
        if node.op == "or" and left is True:
            return True
        right = self.eval(node.right)
        if not is_boolean(right):
            raise EvalError(
                f"'{node.op}' requires booleans, got {_type_name(right)}"
            )
        return right

    def _eval_call(self, node):
        name = node.name
        if name not in BUILTIN_NAMES:
            # Rule 25: function names never fall back to variables.
            raise EvalError(f"undefined function: {name}")
        if name in LAZY_BUILTINS:
            check_if_arity(len(node.args))
            condition = check_if_condition(self.eval(node.args[0]))
            return self.eval(node.args[1] if condition else node.args[2])
        args = [self.eval(arg) for arg in node.args]
        return BUILTINS[name](args)


def evaluate_node(node, env=None):
    """Evaluate an already-parsed AST ``node`` in ``env``."""
    # Rule 31: never mutate the caller's mapping.
    local_env = dict(env) if env else {}
    return _Evaluator(local_env).eval(node)


def evaluate(source, env=None):
    """Parse and evaluate ``source``, returning a ``float``, ``str`` or ``bool``."""
    return evaluate_node(parse(source), env)

"""REPL for minilang: ``python -m minilang``."""

import re
import sys

from .builtins import format_value
from .errors import MiniLangError
from .evaluator import evaluate
from .lexer import KEYWORDS

# Assignments are recognised on the raw line, before lexing, because a lone
# `=` is a LexError in the language itself.
_ASSIGNMENT_RE = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)(.*)$", re.DOTALL)


def run_line(line, env, out):
    """Handle one REPL input line. Returns False when the REPL should stop."""
    stripped = line.strip()
    if not stripped:
        return True

    if stripped == ":quit":
        return False

    if stripped == ":vars":
        for name in sorted(env):
            print(f"{name} = {format_value(env[name])}", file=out)
        return True

    match = _ASSIGNMENT_RE.match(line)
    if match is not None and match.group(1) not in KEYWORDS:
        name, expression = match.group(1), match.group(2)
        try:
            value = evaluate(expression, env)
        except MiniLangError as error:
            print(f"error: {error}", file=out)
        else:
            env[name] = value
        return True

    try:
        value = evaluate(line, env)
    except MiniLangError as error:
        print(f"error: {error}", file=out)
    else:
        print(format_value(value), file=out)
    return True


def main(argv=None):
    env = {}
    for line in sys.stdin:
        if not run_line(line.rstrip("\n"), env, sys.stdout):
            break
    return 0


if __name__ == "__main__":
    sys.exit(main())

